{
  "title": "A Softer Kyoto Morning",
  "summary": "A slower day with one temple, a long lunch, and the evening kept for Pontocho.",
  "stops": [
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": null,
      "note": "One temple, not three. Enough time to actually look at the thousand statues instead of nodding at them."
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch stays. Vegan, unhurried, and close enough to the temple that nobody needs to rush."
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": "m3",
      "note": "The must-do. Shoes off, phone down, eyes up after dark."
    }
  ]
}
